SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE i.member_id = #{memberId}

    AND i.inquiry_id < #{cursor.cursorInquiryId}

ORDER BY i.inquiry_id DESC
LIMIT #{cursor.size}

SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE i.inquiry_id = #{inquiryId}
    AND i.member_id = #{memberId}

SELECT

FROM member_inquiries i
INNER JOIN members m ON m.member_id = i.member_id
WHERE 1 = 1

    AND i.inquiry_status = #{cursor.inquiryStatus}


    AND i.inquiry_id < #{cursor.cursorInquiryId}

ORDER BY i.inquiry_id DESC
LIMIT #{cursor.size}
